-- Import: locations → suppliers → purchases → purchasedetails → sales → saledetails → inventories
-- tenant_id / creator_id match products_import_from_desktop_csv.sql
--   tenant_id  = 10ecd5bb-6d37-4013-a397-e763e3c03bcf
--   creator_id = 6db9a046-43f9-41ac-8de2-971a48fb0dbb (creator_id, receiver_id, and any non-null updated_by)
-- Prerequisites: those rows exist in tenants / users; products for all product_id values;
-- warehouses row id = 1b22ecfe-3048-4266-8d09-bd4f8f1e8530; customers if customer_id is non-null in sales.
-- Inserts a minimal inactive users row for creator_id if that id is still missing.
-- Re-run safety: truncate child tables first or use ON CONFLICT — invoice_number is UNIQUE on purchases/sales.
BEGIN;

-- FK: same creator as products import
SELECT
    '6db9a046-43f9-41ac-8de2-971a48fb0dbb',
    'Data',
    'Import',
    'import-6db9a04643f941ac8de2971a48fb0dbb@ims-csv-import.invalid',
    '+000006db9a046001',
    '10ecd5bb-6d37-4013-a397-e763e3c03bcf',
    now(),
    now(),
    false,
    3
WHERE NOT EXISTS (SELECT 1 FROM users WHERE id = '6db9a046-43f9-41ac-8de2-971a48fb0dbb');








COMMIT;